import { getConfig, getConfigAccountById, getConfigFilePath, getGlobalConfigFilePath, } from '@hubspot/local-dev-lib/config';
import { API_KEY_AUTH_METHOD, PERSONAL_ACCESS_KEY_AUTH_METHOD, } from '@hubspot/local-dev-lib/constants/auth';
import { getAccessToken } from '@hubspot/local-dev-lib/personalAccessKey';
import { uiLogger } from './ui/logger.js';
import { pkg } from './jsonLoader.js';
import { debugError } from './errorHandlers/index.js';
import { isUsageTrackingDisableFlagSet } from './middleware/usageTrackingMiddleware.js';
import { sendUsageEvent, } from './api/usageTracking.js';
const version = pkg.version;
const usageTrackingDiabled = 'Usage tracking is disabled via the --disable-usage-tracking flag, not sending usage events';
export const EventClass = {
    USAGE: 'USAGE',
    INTERACTION: 'INTERACTION',
    VIEW: 'VIEW',
    ACTIVATION: 'ACTIVATION',
};
function getNodeVersionData() {
    return {
        nodeVersion: process.version,
        nodeMajorVersion: (process.version || '').split('.')[0],
    };
}
function getPlatform() {
    switch (process.platform) {
        case 'darwin':
            return 'macos';
        case 'win32':
            return 'windows';
        default:
            return process.platform;
    }
}
function getConfigType() {
    try {
        return getConfigFilePath() === getGlobalConfigFilePath()
            ? 'global'
            : 'local';
    }
    catch (_e) {
        return undefined;
    }
}
function getExecutionSource() {
    if (process.env.HUBSPOT_MCP_AI_AGENT) {
        return 'mcp';
    }
    if (process.env.CI) {
        return 'ci';
    }
    return 'user';
}
export function getExecutionEnvironmentMeta() {
    return {
        os: getPlatform(),
        ...getNodeVersionData(),
        version,
        configType: getConfigType(),
        executionSource: getExecutionSource(),
    };
}
async function getUsageTrackingUserId(accountId) {
    if (!accountId) {
        return undefined;
    }
    try {
        const accountConfig = getConfigAccountById(accountId);
        if (accountConfig.authType !== PERSONAL_ACCESS_KEY_AUTH_METHOD.value) {
            return undefined;
        }
        const accessToken = await getAccessToken(accountConfig.personalAccessKey, accountConfig.env, accountConfig.accountId);
        return typeof accessToken.userId === 'number'
            ? accessToken.userId
            : undefined;
    }
    catch (_e) {
        return undefined;
    }
}
export async function trackCommandUsage(command, meta = {}, accountId) {
    if (isUsageTrackingDisableFlagSet()) {
        uiLogger.debug(usageTrackingDiabled);
        return;
    }
    try {
        const config = getConfig();
        if (config?.allowUsageTracking === false) {
            return;
        }
    }
    catch (e) { }
    uiLogger.debug(`Attempting to track usage of "${command}" command`);
    let authType = 'unknown';
    if (accountId) {
        try {
            const accountConfig = getConfigAccountById(accountId);
            authType =
                accountConfig && accountConfig.authType
                    ? accountConfig.authType
                    : API_KEY_AUTH_METHOD.value;
        }
        catch (e) { }
    }
    return trackCliInteraction({
        action: 'cli-command',
        command,
        authType,
        meta,
        accountId,
    });
}
export async function trackHelpUsage(command) {
    if (isUsageTrackingDisableFlagSet()) {
        uiLogger.debug(usageTrackingDiabled);
        return;
    }
    const config = getConfig();
    if (config?.allowUsageTracking === false) {
        return;
    }
    if (command) {
        uiLogger.debug(`Tracking help usage of "${command}" sub-command`);
    }
    else {
        uiLogger.debug('Tracking help usage of main command');
    }
    return trackCliInteraction({
        action: 'cli-help',
        command,
    });
}
export async function trackConvertFieldsUsage(command) {
    return trackCliInteraction({
        action: 'cli-process-fields',
        command,
    });
}
export async function trackAuthAction(command, authType, step, accountId) {
    return trackCliInteraction({
        action: 'cli-auth',
        command,
        authType,
        accountId,
        meta: {
            step,
        },
    });
}
export async function trackCommandMetadataUsage(command, meta = {}, accountId) {
    if (isUsageTrackingDisableFlagSet()) {
        uiLogger.debug(usageTrackingDiabled);
        return;
    }
    const config = getConfig();
    if (config?.allowUsageTracking === false) {
        return;
    }
    uiLogger.debug(`Attempting to track metadata usage of "${command}" command`);
    let authType = 'unknown';
    if (accountId) {
        const accountConfig = getConfigAccountById(accountId);
        authType =
            accountConfig && accountConfig.authType
                ? accountConfig.authType
                : API_KEY_AUTH_METHOD.value;
    }
    return trackCliInteraction({
        action: 'cli-command-metadata',
        command,
        authType,
        accountId,
        meta,
    });
}
export async function trackMcpPromotionShown(command) {
    return trackCliInteraction({
        action: 'cli-mcp-promotion',
        command: command ?? 'mcp-promotion',
        meta: {
            step: 'shown',
        },
    });
}
async function trackCliInteraction({ action, accountId, command, authType, meta = {}, }) {
    try {
        const config = getConfig();
        if (config?.allowUsageTracking === false) {
            return;
        }
        if (isUsageTrackingDisableFlagSet()) {
            uiLogger.debug(usageTrackingDiabled);
            return;
        }
        const usageTrackingEvent = {
            action,
            command,
            authType,
            ...getExecutionEnvironmentMeta(),
            ...meta,
        };
        try {
            const userId = await getUsageTrackingUserId(accountId);
            const request = {
                eventName: 'cli-interaction',
                eventClass: EventClass.INTERACTION,
                meta: usageTrackingEvent,
                accountId,
            };
            if (userId !== undefined) {
                request.userId = userId;
            }
            uiLogger.debug('Sent usage tracking command event:', usageTrackingEvent);
            await sendUsageEvent(request);
        }
        catch (error) {
            debugError(error);
        }
    }
    catch (e) {
        debugError(e);
    }
}
